23	/**
24	 * Maps Owner & OwnerDto using Mapstruct
25	 */
26	@Mapper(uses = PetMapper.class)
27	public interface OwnerMapper {
28	
29	    @Mapping(target = "selfLink", expression = "java(formatSelfLink(owner))")
30	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
31	    @Mapping(target = "salutation", expression = "java(formatSalutation(owner))")
32	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
33	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
34	    @Mapping(target = "fiscalYear", expression = "java(formatFiscalYear(owner))")
35	    @Mapping(target = "membershipPoints", expression = "java(formatMembershipPoints(owner))")
36	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
37	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
38	    @Mapping(target = "timezone", expression = "java(formatTimezone(owner))")
39	    @Mapping(target = "bulkSignupWarning", expression = "java(formatBulkSignupWarning(owner))")
40	    @Mapping(target = "capacityWarning", expression = "java(formatCapacityWarning(owner))")
41	    @Mapping(target = "possibleDuplicate", expression = "java(formatPossibleDuplicate(owner))")
42	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
43	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
44	    @Mapping(target = "ownerSegment", expression = "java(formatOwnerSegment(owner))")
45	    @Mapping(target = "riskFlag", expression = "java(formatRiskFlag(owner))")
46	    @Mapping(target = "apiVersion", expression = "java(formatApiVersion())")
47	    @Mapping(target = "identity", expression = "java(formatIdentity(owner))")
48	    OwnerDto toOwnerDto(Owner owner);
49	
50	    /** The owner identity contract version carried by every owner response: always {@code 2}. */
51	    default Integer formatApiVersion() {
52	        return 2;
53	    }
54	
55	    /**
56	     * Group the owner's version-2 identifiers into the nested {@code identity} object of the
57	     * response: the {@code memberId}, {@code householdId} and {@code identityKey}, each rederived
58	     * with the version-2 algorithm (see {@link Owner#getIdentityKey()},
59	     * {@link Owner#getHouseholdId()} and the {@code memberId} region derived via
60	     * {@link Regions#forPostcodeV2}). Returns {@code null} only when the owner is {@code null}.
61	     */
62	    default OwnerIdentityDto formatIdentity(Owner owner) {
63	        if (owner == null) {
64	            return null;
65	        }
66	        OwnerIdentityDto identity = new OwnerIdentityDto();
67	        identity.setMemberId(owner.getMemberId());
68	        identity.setHouseholdId(owner.getHouseholdId());
69	        identity.setIdentityKey(owner.getIdentityKey());
70	        return identity;
71	    }
72	
73	    /**
74	     * Derive an owner's risk flag, {@code true} when the owner warrants review because any of
75	     * these hold: the owner is a possible duplicate (see {@link #formatPossibleDuplicate(Owner)}),
76	     * its email domain is disposable-adjacent (see
77	     * {@link DisposableDomains#isDisposableAdjacentEmail(String)}), or its city is over its soft
78	     * capacity (its capacity warning is set, see {@link #formatCapacityWarning(Owner)}); otherwise
79	     * {@code false}. Returns {@code null} only when the owner is {@code null}.
80	     */
81	    default Boolean formatRiskFlag(Owner owner) {
82	        if (owner == null) {
83	            return null;
84	        }
85	        return formatPossibleDuplicate(owner)
86	            || formatCapacityWarning(owner)
87	            || DisposableDomains.isDisposableAdjacentEmail(owner.getEmail());
88	    }
89	
90	    /**
91	     * Derive an owner's marketing segment, formatted {@code "<TIER>_<AREA>"}. The tier is
92	     * {@code "PREMIUM"} when the owner's {@code membershipLevel} (see
93	     * {@link #formatMembershipLevel(Owner)}) is {@code 3} or more, otherwise {@code "STANDARD"}.
94	     * The area is {@code "METRO"} when the owner's locality (see {@link #formatLocality(Owner)}) is
95	     * a known region (NSW, VIC or QLD), otherwise {@code "REGIONAL"}. Returns one of
96	     * {@code "PREMIUM_METRO"}, {@code "PREMIUM_REGIONAL"}, {@code "STANDARD_METRO"} or
97	     * {@code "STANDARD_REGIONAL"}; {@code null} only when the owner is {@code null}.
98	     */
99	    default String formatOwnerSegment(Owner owner) {
100	        if (owner == null) {
101	            return null;
102	        }
103	        Integer level = formatMembershipLevel(owner);
104	        String tier = level != null && level >= 3 ? "PREMIUM" : "STANDARD";
105	        String area = Regions.isKnownRegion(formatLocality(owner)) ? "METRO" : "REGIONAL";
106	        return tier + "_" + area;
107	    }
108	
109	    /**
110	     * Resolve an owner's possible-duplicate flag, coalescing a {@code null} stored value
111	     * (e.g. for owners created before the flag existed) to {@code false} so the response
112	     * always carries an explicit boolean.
113	     */
114	    default Boolean formatPossibleDuplicate(Owner owner) {
115	        if (owner == null) {
116	            return null;
117	        }
118	        return Boolean.TRUE.equals(owner.getPossibleDuplicate());
119	    }
120	
121	    /**
122	     * Derive an owner's age band from its {@code birthDate}, measured as the owner's age in whole
123	     * years on its {@code registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18
124	     * through 64, and {@code "SENIOR"} at 65 and over. Returns {@code null} when the owner, its
125	     * birth date or its registration date is absent, since the band cannot be derived without both
126	     * dates.
127	     */
128	    default String formatAgeBand(Owner owner) {
129	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
130	            return null;
131	        }
132	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
133	        if (age < 18) {
134	            return "MINOR";
135	        }
136	        if (age < 65) {
137	            return "ADULT";
138	        }
139	        return "SENIOR";
140	    }
141	
142	    /**
143	     * Derive an owner's preferred contact channel from its stored contact details:
144	     * {@code "EMAIL"} when a (non-blank) email address is present, otherwise {@code "PHONE"}.
145	     */
146	    default String formatContactPreference(Owner owner) {
147	        if (owner == null) {
148	            return null;
149	        }
150	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
151	        return hasEmail ? "EMAIL" : "PHONE";
152	    }
153	
154	    /**
155	     * Resolve an owner's bulk-signup warning flag, coalescing a {@code null} stored value
156	     * (e.g. for owners created before the flag existed) to {@code false} so the response
157	     * always carries an explicit boolean.
158	     */
159	    default Boolean formatBulkSignupWarning(Owner owner) {
160	        if (owner == null) {
161	            return null;
162	        }
163	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
164	    }
165	
166	    /**
167	     * Resolve an owner's capacity-warning flag, coalescing a {@code null} stored value
168	     * (e.g. for owners created before the flag existed) to {@code false} so the response
169	     * always carries an explicit boolean.
170	     */
171	    default Boolean formatCapacityWarning(Owner owner) {
172	        if (owner == null) {
173	            return null;
174	        }
175	        return Boolean.TRUE.equals(owner.getCapacityWarning());
176	    }
177	
178	    /**
179	     * Derive an owner's locality as the plain region code derived from its postcode (see
180	     * {@link Regions#forPostcode}), e.g. {@code "NSW"} or {@code "UNKNOWN"}. The locality is a
181	     * user-facing field, not an identifier, so it always carries the plain region code and never
182	     * the version-2 identity tag mixed into the {@code memberId}'s region segment (see
183	     * {@link Regions#forPostcodeV2}). Returns {@code null} only when the owner itself is
184	     * {@code null}.
185	     */
186	    default String formatLocality(Owner owner) {
187	        if (owner == null) {
188	            return null;
189	        }
190	        return Regions.forPostcode(owner.getPostcode());
191	    }
192	
193	    /**
194	     * Derive an owner's timezone as the IANA name mapped from its locality/region via a fixed
195	     * region-to-timezone table (see {@link Regions#timezoneForRegion}): NSW -> Australia/Sydney,
196	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane. Returns {@code null} when the owner
197	     * is {@code null} or its region is not in the table.
198	     */
199	    default String formatTimezone(Owner owner) {
200	        if (owner == null) {
201	            return null;
202	        }
203	        return Regions.timezoneForRegion(formatLocality(owner));
204	    }
205	
206	    /**
207	     * Compute an owner's membership points. Points start at {@code 0} and gain: {@code 2} when an
208	     * email address is present; {@code 1} when the owner has no namesakes (its
209	     * {@code namesakeCount} is {@code 0}); {@code 2} for a household of three or more members (the
210	     * owner plus its pets); and {@code 3} when the owner's tenure (the number of fiscal years
211	     * elapsed since its {@code registrationDate}'s fiscal year) exceeds {@code 1}. A null or absent
212	     * namesake count is treated as not being zero, so it contributes nothing.
213	     */
214	    default Integer formatMembershipPoints(Owner owner) {
215	        if (owner == null) {
216	            return null;
217	        }
218	        int points = 0;
219	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
220	        if (hasEmail) {
221	            points += 2;
222	        }
223	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
224	        if (uniqueName) {
225	            points += 1;
226	        }
227	        int householdSize = 1 + (owner.getPets() == null ? 0 : owner.getPets().size());
228	        if (householdSize >= 3) {
229	            points += 2;
230	        }
231	        LocalDate registrationDate = owner.getRegistrationDate();
232	        if (registrationDate != null
233	            && BusinessDays.fiscalYearEndYear(LocalDate.now())
234	                - BusinessDays.fiscalYearEndYear(registrationDate) > 1) {
235	            points += 3;
236	        }
237	        return points;
238	    }
239	
240	    /**
241	     * Determine an owner's membership level, a number from {@code 1} to {@code 4} derived from its
242	     * membership points (see {@link #formatMembershipPoints(Owner)}): level {@code 1} for
243	     * {@code 0}-{@code 1} points, {@code 2} for {@code 2}-{@code 3}, {@code 3} for {@code 4}-{@code 5}
244	     * and {@code 4} for {@code 6} or more.
245	     *
246	     * <p>The level is then capped by the owner's {@code membershipLevelCap} when one is present (see
247	     * {@link Owner#getMembershipLevelCap()}): a new owner's level may not exceed one above the
248	     * current maximum level among its existing household members, so the returned value is the
249	     * smaller of the points-derived level and the cap. A {@code null} cap means no household ceiling
250	     * applies and the points-derived level is returned unchanged.
251	     */
252	    default Integer formatMembershipLevel(Owner owner) {
253	        if (owner == null) {
254	            return null;
255	        }
256	        int points = formatMembershipPoints(owner);
257	        int level;
258	        if (points <= 1) {
259	            level = 1;
260	        }
261	        else if (points <= 3) {
262	            level = 2;
263	        }
264	        else if (points <= 5) {
265	            level = 3;
266	        }
267	        else {
268	            level = 4;
269	        }
270	        Integer cap = owner.getMembershipLevelCap();
271	        if (cap != null && cap < level) {
272	            return cap;
273	        }
274	        return level;
275	    }
276	
277	    /**
278	     * Format an owner's fiscal year as {@code "FY<YY>"}, where {@code YY} is the 2-digit fiscal
279	     * year the owner's (business-day-adjusted) {@code registrationDate} falls in. The fiscal year
280	     * starts on 1 July and is named by the calendar year in which it ends, so a registration date
281	     * of {@code 2026-07-01} is {@code "FY27"} while {@code 2026-06-30} is {@code "FY26"}. This is
282	     * the same fiscal year the {@code memberId}'s {@code <FY>} segment carries, derived directly
283	     * from the registration date so it is independent of the version-2 tag mixed into the
284	     * {@code memberId}'s region segment. Returns {@code null} when the owner or its registration
285	     * date is absent.
286	     */
287	    default String formatFiscalYear(Owner owner) {
288	        if (owner == null || owner.getRegistrationDate() == null) {
289	            return null;
290	        }
291	        return String.format("FY%02d", BusinessDays.fiscalYearEndYear(owner.getRegistrationDate()) % 100);
292	    }
293	
294	    /**
295	     * Format an owner's stored E.164 telephone for humans as the country code, a space, then the
296	     * national digits grouped in threes, e.g. {@code "+61412345678"} becomes
297	     * {@code "+61 412 345 678"} (see {@link E164Telephone#toDisplay}). The raw {@code telephone}
298	     * is left in E.164 form. Returns {@code null} when the owner or its telephone is absent.
299	     */
300	    default String formatTelephoneDisplay(Owner owner) {
301	        if (owner == null) {
302	            return null;
303	        }
304	        return E164Telephone.toDisplay(owner.getTelephone());
305	    }
306	
307	    /**
308	     * Compose an owner's salutation as its {@code title} followed by a single space and the
309	     * last name (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the
310	     * salutation is just the last name. Returns {@code null} when the owner is {@code null}.
311	     */
312	    default String formatSalutation(Owner owner) {
313	        if (owner == null) {
314	            return null;
315	        }
316	        String title = owner.getTitle();
317	        if (title == null || title.trim().isEmpty()) {
318	            return owner.getLastName();
319	        }
320	        return title + " " + owner.getLastName();
321	    }
322	
323	    /**
324	     * Build a link to an owner's own resource, formed as {@code "/api/owners/"} followed by the
325	     * owner's id. Returns {@code null} when the owner or its id is absent, since the link cannot
326	     * be formed without an id.
327	     */
328	    default String formatSelfLink(Owner owner) {
329	        if (owner == null || owner.getId() == null) {
330	            return null;
331	        }
332	        return "/api/owners/" + owner.getId();
333	    }
334	
335	    /**
336	     * Format an owner's name as {@code "LastName, FirstName"} from the stored names.
337	     */
338	    default String formatDisplayName(Owner owner) {
339	        if (owner == null) {
340	            return null;
341	        }
342	        return owner.getLastName() + ", " + owner.getFirstName();
343	    }
344	
345	    /**
346	     * Format an owner's initials as the upper-cased first letters of the first and last
347	     * names, dot-separated with a trailing dot, e.g. {@code "J.S."}.
348	     */
349	    default String formatInitials(Owner owner) {
350	        if (owner == null) {
351	            return null;
352	        }
353	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
354	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
355	    }
356	
357	    Owner toOwner(OwnerDto ownerDto);
358	
359	    @Mapping(target = "id", ignore = true)
360	    @Mapping(target = "pets", ignore = true)
361	    @Mapping(target = "namesakeCount", ignore = true)
362	    @Mapping(target = "bulkSignupWarning", ignore = true)
363	    @Mapping(target = "capacityWarning", ignore = true)
364	    @Mapping(target = "possibleDuplicate", ignore = true)
365	    @Mapping(target = "possibleDuplicateOf", ignore = true)
366	    @Mapping(target = "membershipLevelCap", ignore = true)
367	    @Mapping(target = "address", expression = "java(composeAddress(ownerDto))")
368	    @Mapping(target = "addressLine1", source = "addressLine1", qualifiedByName = "normalizeAddress")
369	    @Mapping(target = "addressLine2", source = "addressLine2", qualifiedByName = "normalizeAddress")
370	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
371	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
372	    Owner toOwner(OwnerFieldsDto ownerDto);
373	
374	    /**
375	     * Normalize a postal address for storage into its canonical form (see
376	     * {@link AddressNormalizer}), so it is persisted and returned the same way regardless of
377	     * the formatting supplied by the caller. {@code @Named} keeps this out of MapStruct's
378	     * automatic method selection, so it only runs where a mapping explicitly references it via
379	     * {@code qualifiedByName}.
380	     */
381	    @Named("normalizeAddress")
382	    default String normalizeAddress(String address) {
383	        return AddressNormalizer.normalize(address);
384	    }
385	
386	    /**
387	     * Compose the single stored/returned {@code address} from whichever address fields the request
388	     * supplies, preferring the structured form. When a non-blank {@code addressLine1} is present the
389	     * composed value is the normalized {@code addressLine1} (see {@link AddressNormalizer}), with a
390	     * single space and the normalized {@code addressLine2} appended when {@code addressLine2} is
391	     * present; otherwise it falls back to the normalized flat {@code address}. This keeps everything
392	     * that reads the stored address consistent regardless of which form the caller used.
393	     */
394	    default String composeAddress(OwnerFieldsDto ownerDto) {
395	        if (ownerDto == null) {
396	            return null;
397	        }
398	        String line1 = ownerDto.getAddressLine1();
399	        if (line1 != null && !line1.trim().isEmpty()) {
400	            String composed = AddressNormalizer.normalize(line1);
401	            String line2 = ownerDto.getAddressLine2();
402	            if (line2 != null && !line2.trim().isEmpty()) {
403	                composed = composed + " " + AddressNormalizer.normalize(line2);
404	            }
405	            return composed;
406	        }
407	        return AddressNormalizer.normalize(ownerDto.getAddress());
408	    }
409	
410	    /**
411	     * Normalize a telephone number for storage into E.164 form (see {@link E164Telephone}).
412	     * The requirement that a valid E.164 number can be formed is enforced separately by
413	     * {@code TelephoneValidation}, so for already-validated input this returns the E.164
414	     * string; it is idempotent, so re-normalizing a stored value yields the same value.
415	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
416	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
417	     */
418	    @Named("normalizeTelephone")
419	    default String normalizeTelephone(String telephone) {
420	        return E164Telephone.normalize(telephone);
421	    }
422	
423	    /**
424	     * Normalize an email address for storage by lower-casing it, so it is persisted and
425	     * returned in a canonical form regardless of the casing supplied by the caller.
426	     * Syntactic validity is enforced separately by the {@code @Email} constraint on the DTO.
427	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
428	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
429	     */
430	    @Named("normalizeEmail")
431	    default String normalizeEmail(String email) {
432	        return email == null ? null : email.toLowerCase();
433	    }
434	
435	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
436	
437	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
438	
439	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
440	        OwnerPageDto ownerPageDto = new OwnerPageDto();
441	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
442	        ownerPageDto.setPage(ownerPage.getNumber());
443	        ownerPageDto.setSize(ownerPage.getSize());
444	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
445	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
446	        return ownerPageDto;
447	    }
448	}
